INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7734924, 1275048, 96751, '<td valign="top">I love this. Normally I hate tilts, but somehow this adds to the tension of this person in the dark corner, watching the whirling machines. Masterful edit.</td>', 'I love this. Normally I hate tilts, but somehow this adds to the tension of this person in the dark corner, watching the whirling machines. Masterful edit.', '2022-12-19 00:24:16.000000', NULL, 1),
(7734926, 1275059, 96751, '<td valign="top">We''re of the same mind. That little splash of yellow is perfect.</td>', 'We''re of the same mind. That little splash of yellow is perfect.', '2022-12-19 00:25:31.000000', NULL, 1),
(7734927, 1275029, 96751, '<td valign="top">I know where this is.<br/>I know who this is.</td>', 'I know where this is.I know who this is.', '2022-12-19 00:27:18.000000', NULL, 1),
(7734935, 1275001, 83313, '<td valign="top">Pegging this one as a ribbon or HM at minimum.</td>', 'Pegging this one as a ribbon or HM at minimum.', '2022-12-19 01:18:36.000000', NULL, 1),
(7734936, 1275040, 83313, '<td valign="top">Of course not, kitty ate the mouse.</td>', 'Of course not, kitty ate the mouse.', '2022-12-19 01:19:33.000000', NULL, 1),
(7734937, 1274817, 83313, '<td valign="top">Awww! Sweet pupper.</td>', 'Awww! Sweet pupper.', '2022-12-19 01:21:11.000000', NULL, 1),
(7734938, 1274817, 29535, '<td valign="top">So hard to get these perfect portraits of our pets! Love the expression and I think you did very well with the composition in a difficult situation to photograph nicely. Good job.</td>', 'So hard to get these perfect portraits of our pets! Love the expression and I think you did very well with the composition in a difficult situation to photograph nicely. Good job.', '2022-12-19 01:25:18.000000', NULL, 1),
(7734939, 1275026, 29535, '<td valign="top">Lovely composition bringing in the chair back and its shadow. Gives me inspiration for photographing my own dog (as if I need any more reason to do so, he''s practically all I shoot!) Good job!</td>', 'Lovely composition bringing in the chair back and its shadow. Gives me inspiration for photographing my own dog (as if I need any more reason to do so, he''s practically all I shoot!) Good job!', '2022-12-19 01:26:20.000000', NULL, 1),
(7734940, 1274996, 29535, '<td valign="top">This is a really good execution of a simple shot. I see there are some really good shots for this challenge with more interesting subjects so it''s not going to make my top picks, but you''ve achieved something admirable and difficult in make the mundane quite beautiful.</td>', 'This is a really good execution of a simple shot. I see there are some really good shots for this challenge with more interesting subjects so it''s not going to make my top picks, but you''ve achieved something admirable and difficult in make the mundane quite beautiful.', '2022-12-19 01:27:34.000000', NULL, 1),
(7734941, 1274891, 29535, '<td valign="top">Love it. When looking to water as your subject in such a challenge finding the perfect focal point is the real difficulty, and you nailed it with this isolated branch.</td>', 'Love it. When looking to water as your subject in such a challenge finding the perfect focal point is the real difficulty, and you nailed it with this isolated branch.', '2022-12-19 01:28:17.000000', NULL, 1),
(7734943, 1275052, 29535, '<td valign="top">It''s clear there was a struggle with the processing of the sky there probably due to the timing of the shot but man that is a composition one can''t pass up (if we''re good enough to spot it!) I love it.</td>', 'It''s clear there was a struggle with the processing of the sky there probably due to the timing of the shot but man that is a composition one can''t pass up (if we''re good enough to spot it!) I love it.', '2022-12-19 01:29:56.000000', NULL, 1),
(7734944, 1275047, 29535, '<td valign="top">It''s a cute shot, and almost looks like a publicity image with its technical aspects. But I''m not sure it fits well with the challenge theme and the entries so far have been strong. Great exposure though.</td>', 'It''s a cute shot, and almost looks like a publicity image with its technical aspects. But I''m not sure it fits well with the challenge theme and the entries so far have been strong. Great exposure though.', '2022-12-19 01:30:51.000000', NULL, 1),
(7734945, 1274988, 29535, '<td valign="top">It''s a simple idea competing against a strong selection of images in this contest, but overall I think you achieved what you wanted and it fits the challenge theme just about. I like how dark the background is to isolate the candle, perhaps I would''ve liked to see a little light on the candle itself, but that''s subjective.</td>', 'It''s a simple idea competing against a strong selection of images in this contest, but overall I think you achieved what you wanted and it fits the challenge theme just about. I like how dark the background is to isolate the candle, perhaps I would''ve liked to see a little light on the candle itself, but that''s subjective.', '2022-12-19 01:31:49.000000', NULL, 1),
(7734946, 1275049, 29535, '<td valign="top">A great example of how a good composition and well-executed photo can turn a family snapshot into an art piece. Looks wonderful. This is a strong challenge, I''m excited to see the results!</td>', 'A great example of how a good composition and well-executed photo can turn a family snapshot into an art piece. Looks wonderful. This is a strong challenge, I''m excited to see the results!', '2022-12-19 01:32:43.000000', NULL, 1),
(7734947, 1275018, 29535, '<td valign="top">Quite abstract in its execution focusing on reflections, light and colours rather than physical subjects but I love it for this. And who doesn''t love a frozen lake? Good challenge fit and nice shot. This seems like a strong challenge though so it''s all to play for.</td>', 'Quite abstract in its execution focusing on reflections, light and colours rather than physical subjects but I love it for this. And who doesn''t love a frozen lake? Good challenge fit and nice shot. This seems like a strong challenge though so it''s all to play for.', '2022-12-19 01:33:35.000000', NULL, 1),
(7734948, 1275023, 29535, '<td valign="top">I''m so glad you returned - this composition is much improved IMO and I think it fits the theme even better than previously. Well done!</td>', 'I''m so glad you returned - this composition is much improved IMO and I think it fits the theme even better than previously. Well done!', '2022-12-19 01:34:13.000000', NULL, 1),
(7734952, 1275001, 114285, '<td valign="top">Absolutely beautiful, be hard to beat this one.<br/> <br/>Love the softness and low contrast feel to this shot. The blue or red.<br/> <br/>I''m guessing it''s Coley :) That''s a compliment.</td>', 'Absolutely beautiful, be hard to beat this one. Love the softness and low contrast feel to this shot. The blue or red. I''m guessing it''s Coley :) That''s a compliment.', '2022-12-19 02:49:14.000000', NULL, 1),
(7734970, 1275001, 29535, '<td valign="top">I''m so jealous you got this. I''m really looking to get into more woodland photography and am waiting for the right conditions and timing, just missed our first snow! Love the way the path is hinted at going into the photo and the trees disappearing into the fog. My pick so far.</td>', 'I''m so jealous you got this. I''m really looking to get into more woodland photography and am waiting for the right conditions and timing, just missed our first snow! Love the way the path is hinted at going into the photo and the trees disappearing into the fog. My pick so far.', '2022-12-19 10:09:19.000000', NULL, 1),
(7734971, 1275024, 29535, '<td valign="top">You''ve got a really good eye for composition here, although your camera is clearly struggling with the zoom. The lighting is great, black and white is the right choice.<br/> <br/>Unfortunately I don''t think it really fits the challenge theme well. But it shows you have a good eye for composition and I look forward to seeing more!</td>', 'You''ve got a really good eye for composition here, although your camera is clearly struggling with the zoom. The lighting is great, black and white is the right choice. Unfortunately I don''t think it really fits the challenge theme well. But it shows you have a good eye for composition and I look forward to seeing more!', '2022-12-19 10:10:23.000000', NULL, 1),
(7734973, 1275003, 29535, '<td valign="top">As I said on the other snowy woodland photo from this contest I''m quite jealous that you managed to get out and shoot just as the conditions were right, I missed them myself and will have to wait for the next snowfall. This is an interesting composition with the hill and the horizon requiring the viewer to spend a good amount of time exploring every detail and line.<br/> <br/>I think it would have been a much better fit for the theme had the path in front not been previously disturbed, a fresh blanket of snow would''ve made it more impressive IMO. Good shot but it has some tough competition, good luck!</td>', 'As I said on the other snowy woodland photo from this contest I''m quite jealous that you managed to get out and shoot just as the conditions were right, I missed them myself and will have to wait for the next snowfall. This is an interesting composition with the hill and the horizon requiring the viewer to spend a good amount of time exploring every detail and line. I think it would have been a much better fit for the theme had the path in front not been previously disturbed, a fresh blanket of snow would''ve made it more impressive IMO. Good shot but it has some tough competition, good luck!', '2022-12-19 10:12:33.000000', NULL, 1),
(7734974, 1275040, 29535, '<td valign="top">This is a lovely shot of a nice moment. The cat is super sharp and I love that you can see every hair in detail.<br/> <br/>I''m not convinced it''s the best fit for the contest despite the title... but I like the photo :)</td>', 'This is a lovely shot of a nice moment. The cat is super sharp and I love that you can see every hair in detail. I''m not convinced it''s the best fit for the contest despite the title... but I like the photo :)', '2022-12-19 10:13:31.000000', NULL, 1),
(7734975, 1275021, 29535, '<td valign="top">I really like the way the lighting has turned out in this shot, although my eye is struggling to find a sharp object to focus on as the lights are a little fuzzy and nothing else is grabbing me. I think the overall exposure is very cool though.<br/> <br/>Despite the title... I''m not a big fan of this for the Stillness challenge. There''s some tough competition in this one. Good luck though, and I look forward to experimenting myself with Christmas tree lighting as it creates a really nice glow here!</td>', 'I really like the way the lighting has turned out in this shot, although my eye is struggling to find a sharp object to focus on as the lights are a little fuzzy and nothing else is grabbing me. I think the overall exposure is very cool though. Despite the title... I''m not a big fan of this for the Stillness challenge. There''s some tough competition in this one. Good luck though, and I look forward to experimenting myself with Christmas tree lighting as it creates a really nice glow here!', '2022-12-19 10:15:27.000000', NULL, 1),
(7734977, 1275059, 29535, '<td valign="top">Whilst I''m not a fan of this as far as meeting the challenge (the puddle may be still but a city street doesn''t scream tranquility to me...) this is an excellent example pulling a fantastic composition out of nothing, with the reflections and cobbles and colours all combining to make a really interesting out of the box shot.<br/> <br/>I love the flashes of yellow balanced between the lantern and the bricks and leaves. It''s a really nice spot and I wish I had the eye that could pick out such a composition.</td>', 'Whilst I''m not a fan of this as far as meeting the challenge (the puddle may be still but a city street doesn''t scream tranquility to me...) this is an excellent example pulling a fantastic composition out of nothing, with the reflections and cobbles and colours all combining to make a really interesting out of the box shot. I love the flashes of yellow balanced between the lantern and the bricks and leaves. It''s a really nice spot and I wish I had the eye that could pick out such a composition.', '2022-12-19 10:18:47.000000', NULL, 1),
(7734979, 1275053, 29535, '<td valign="top">This is a decent shot, and I think It fits with the stillness theme well. The colours are a little oversaturated for my taste and the sky is blowing out a bit, but I think with the light you had available you''ve handled it pretty well. Personally I would love to see a slightly different composition, perhaps without the tree and its reflection so central but it''s hard to tell from the shot where else you have room to move. Perhaps this location has more potential!</td>', 'This is a decent shot, and I think It fits with the stillness theme well. The colours are a little oversaturated for my taste and the sky is blowing out a bit, but I think with the light you had available you''ve handled it pretty well. Personally I would love to see a slightly different composition, perhaps without the tree and its reflection so central but it''s hard to tell from the shot where else you have room to move. Perhaps this location has more potential!', '2022-12-19 10:20:44.000000', NULL, 1),
(7734980, 1275030, 29535, '<td valign="top">This is a wonderful shot of one of my favourite critters. Everything crisp sharp, the background perfect and exposure all coming together to make a wonderful image. Stillness... I''m not seeing it despite the title ;) I love the chubby little fella and it''s a great shot but I think there are better fits for this particular contest unfortunately :(</td>', 'This is a wonderful shot of one of my favourite critters. Everything crisp sharp, the background perfect and exposure all coming together to make a wonderful image. Stillness... I''m not seeing it despite the title ;) I love the chubby little fella and it''s a great shot but I think there are better fits for this particular contest unfortunately :(', '2022-12-19 10:22:40.000000', NULL, 1),
(7734983, 1275031, 29535, '<td valign="top">Love it when the rays of sunlight are coming down through the clouds like that. I think I''d like to have seen this with one''s back to the sun, as it''s blown out the sky a little too much. Nice match for the challenge.</td>', 'Love it when the rays of sunlight are coming down through the clouds like that. I think I''d like to have seen this with one''s back to the sun, as it''s blown out the sky a little too much. Nice match for the challenge.', '2022-12-19 10:33:35.000000', NULL, 1),
(7734984, 1274897, 29535, '<td valign="top">I love the composition here and the colours paired between the kayaker and the buildings behind. I do get a big sense of movement from our subject though... but I suppose it''s nice he''s cutting through the ''stillness'' of the water.</td>', 'I love the composition here and the colours paired between the kayaker and the buildings behind. I do get a big sense of movement from our subject though... but I suppose it''s nice he''s cutting through the ''stillness'' of the water.', '2022-12-19 10:35:21.000000', NULL, 1),
(7734986, 1275029, 29535, '<td valign="top">I find woodland photography both wonderful and incredibly difficult due to the chaos. I think you''ve found a good spot here on a day with decent conditions. But something about it feels a little rushed. Perhaps the disembodied branch in the top right, the horizon line that I''m not quite convinced is straight... I''d love to see a re-crop as I think there''s a much better composition hiding in this very shot, you may also have others from the day.<br/> <br/>Fits the challenge nicely though!</td>', 'I find woodland photography both wonderful and incredibly difficult due to the chaos. I think you''ve found a good spot here on a day with decent conditions. But something about it feels a little rushed. Perhaps the disembodied branch in the top right, the horizon line that I''m not quite convinced is straight... I''d love to see a re-crop as I think there''s a much better composition hiding in this very shot, you may also have others from the day. Fits the challenge nicely though!', '2022-12-19 10:40:27.000000', NULL, 1),
(7734987, 1274958, 29535, '<td valign="top">Love where rock meets water. This feels a little softer than the usual DPC compression... I think it''s a decent subject choice but I''d love to have seen a little more of something, perhaps another object of interest.</td>', 'Love where rock meets water. This feels a little softer than the usual DPC compression... I think it''s a decent subject choice but I''d love to have seen a little more of something, perhaps another object of interest.', '2022-12-19 10:41:19.000000', NULL, 1),
(7734988, 1274943, 29535, '<td valign="top">This is a nice, soft and well-executed portrait shot with a subtle vignette that I think works perfectly. I don''t associate crashing out on a table with the kind of ''stillness'' sleep one would get lay down, but it''s a good shot that I guess just about fits into the challenge. Great colour work too, soft pastels all over and perfect skin tone.</td>', 'This is a nice, soft and well-executed portrait shot with a subtle vignette that I think works perfectly. I don''t associate crashing out on a table with the kind of ''stillness'' sleep one would get lay down, but it''s a good shot that I guess just about fits into the challenge. Great colour work too, soft pastels all over and perfect skin tone.', '2022-12-19 10:42:36.000000', NULL, 1),
(7734989, 1275033, 29535, '<td valign="top">I''m sorry I think you chose the wrong composition for this one and not the most ideal challenge fit. It''s also a little too soft so I don''t know where I''m supposed to be looking. Your camera seems to be struggling with the light available too... There''s perhaps a nice countryside composition in there just outside the window (if that is a window you''re shooting through) that would improve this shot massively.</td>', 'I''m sorry I think you chose the wrong composition for this one and not the most ideal challenge fit. It''s also a little too soft so I don''t know where I''m supposed to be looking. Your camera seems to be struggling with the light available too... There''s perhaps a nice countryside composition in there just outside the window (if that is a window you''re shooting through) that would improve this shot massively.', '2022-12-19 10:44:15.000000', NULL, 1),
(7734992, 1274915, 70896, '<td valign="top">Looks beautiful and calm! I would have personally cropped off a bit from the top and made the bottom half a bit lighter. Great job!</td>', 'Looks beautiful and calm! I would have personally cropped off a bit from the top and made the bottom half a bit lighter. Great job!', '2022-12-19 11:19:24.000000', NULL, 1),
(7734994, 1274923, 29535, '<td valign="top">Great capture of a difficult subject. Is the sun rising or setting behind there? Lighting the sky seems like it will always be difficult at this location but I''d love to see another go in different conditions as this could be a real gem.</td>', 'Great capture of a difficult subject. Is the sun rising or setting behind there? Lighting the sky seems like it will always be difficult at this location but I''d love to see another go in different conditions as this could be a real gem.', '2022-12-19 11:20:49.000000', NULL, 1),
(7734995, 1274817, 30049, '<td valign="top">:-)</td>', ':-)', '2022-12-19 11:21:56.000000', NULL, 1),
(7734996, 1275053, 30049, '<td valign="top">That''s because nobody can get to it with that fence over there.  LOL  Oh, wait, you were able to access it.  Nevermind.  :-)</td>', 'That''s because nobody can get to it with that fence over there.  LOL  Oh, wait, you were able to access it.  Nevermind.  :-)', '2022-12-19 11:23:08.000000', NULL, 1),
(7734997, 1274943, 30049, '<td valign="top">Nice idea, but looks seriously posed.  I mean, who sleeps on a hard surface like that?  I guess maybe some do, if they''re really, really worn out.</td>', 'Nice idea, but looks seriously posed.  I mean, who sleeps on a hard surface like that?  I guess maybe some do, if they''re really, really worn out.', '2022-12-19 11:24:10.000000', NULL, 1),
(7734998, 1274923, 30049, '<td valign="top">Lovely mirror image.</td>', 'Lovely mirror image.', '2022-12-19 11:24:50.000000', NULL, 1),
(7735003, 1275059, 123833, '<td valign="top">Great PP</td>', 'Great PP', '2022-12-19 12:10:20.000000', NULL, 1),
(7735004, 1275001, 123833, '<td valign="top">Looks almost Unreal</td>', 'Looks almost Unreal', '2022-12-19 12:10:40.000000', NULL, 1),
(7735011, 1274943, 86447, '<td valign="top">"Sweet Dreams" is correct   (no apostrophe)<br/> <br/>SC will fix it for you if you ask them.<br/> <br/>lovely image!</td>', '"Sweet Dreams" is correct   (no apostrophe) SC will fix it for you if you ask them. lovely image!', '2022-12-19 13:12:19.000000', NULL, 1),
(7735012, 1275018, 86447, '<td valign="top">Oh!  This is lovely!  I love the little pops of color.</td>', 'Oh!  This is lovely!  I love the little pops of color.', '2022-12-19 13:12:56.000000', NULL, 1),
(7735013, 1275029, 86447, '<td valign="top">This is gorgeous!  But... I''m so thankful that it was you there instead of me.  Ha!</td>', 'This is gorgeous!  But... I''m so thankful that it was you there instead of me.  Ha!', '2022-12-19 13:13:42.000000', NULL, 1),
(7735014, 1275001, 86447, '<td valign="top">I love this!  I love how it appears to be a black and white image... but then we find the brown of the grass.   Brilliantly done.</td>', 'I love this!  I love how it appears to be a black and white image... but then we find the brown of the grass.   Brilliantly done.', '2022-12-19 13:15:00.000000', NULL, 1),
(7735040, 1275048, 91360, '<td valign="top">great image! love the PP.</td>', 'great image! love the PP.', '2022-12-20 00:00:27.000000', NULL, 1),
